create or replace function catalog._product_business_status_result_row(
  p_tenant_id uuid,
  p_product_id uuid,
  p_previous_status text,
  p_current_status text,
  p_reason text,
  p_warnings jsonb,
  p_history_id uuid
)
returns table (
  product_id uuid,
  previous_status text,
  current_status text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer,
  reason text,
  warnings jsonb,
  history_entry jsonb
)
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select
    p.id as product_id,
    p_previous_status as previous_status,
    p_current_status as current_status,
    r.status::text as readiness_status,
    coalesce(r.blockers, '[]'::jsonb) as readiness_blockers,
    p.version,
    nullif(btrim(coalesce(p_reason, '')), '') as reason,
    coalesce(p_warnings, '[]'::jsonb) as warnings,
    case
      when h.id is null then null
      else jsonb_build_object(
        'id', h.id,
        'occurred_at', h.created_at,
        'actor_display_name', left(h.actor_id::text, 8),
        'change_type', 'product_status_changed',
        'summary', case
          when p_current_status = 'inactive' then 'Ngừng kinh doanh sản phẩm'
          else 'Kinh doanh lại sản phẩm'
        end,
        'value_before', p_previous_status,
        'value_after', p_current_status
      )
    end as history_entry
  from catalog.products p
  left join catalog.product_readiness r
    on r.product_id = p.id
   and r.tenant_id = p.tenant_id
  left join catalog.product_change_history h
    on h.id = p_history_id
   and h.product_id = p.id
   and h.tenant_id = p.tenant_id
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id;
$$;

create or replace function catalog._product_business_status_warnings(
  p_tenant_id uuid,
  p_product_id uuid
)
returns jsonb
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select coalesce(jsonb_agg(warning), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'code', 'has_stock',
      'message', 'Sản phẩm vẫn còn tồn kho hiện hành.'
    ) as warning
    where exists (
      select 1
      from catalog.product_stock_profiles sp
      where sp.tenant_id = p_tenant_id
        and sp.product_id = p_product_id
        and coalesce(sp.initial_stock, 0) > 0
    )
  ) warnings;
$$;

create or replace function catalog.deactivate_product(
  p_tenant_id uuid,
  p_product_id uuid,
  p_actor_id uuid default auth.uid(),
  p_reason text default null,
  p_expected_version integer default null,
  p_confirm_acknowledge_warnings boolean default false
)
returns table (
  product_id uuid,
  previous_status text,
  current_status text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer,
  reason text,
  warnings jsonb,
  history_entry jsonb
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_previous_status text;
  v_current_status text := 'inactive';
  v_warnings jsonb := '[]'::jsonb;
  v_history_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_status') then
    raise exception 'permission denied: catalog.product.manage_status';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.deleted_at is not null then
    raise exception 'product is soft-deleted and cannot change business status';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  if v_product.business_status = 'inactive'::catalog.product_business_status then
    raise exception 'validation_exception: Product is already inactive.';
  end if;

  v_warnings := catalog._product_business_status_warnings(p_tenant_id, p_product_id);
  if jsonb_array_length(v_warnings) > 0 and not coalesce(p_confirm_acknowledge_warnings, false) then
    raise exception 'product_business_status_warnings_require_acknowledgment: %',
      v_warnings::text;
  end if;

  v_previous_status := v_product.business_status::text;

  update catalog.products
  set business_status = 'inactive',
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    p_product_id,
    'product_status_changed',
    jsonb_build_object(
      'value_before', v_previous_status,
      'value_after', v_current_status,
      'reason', nullif(btrim(coalesce(p_reason, '')), ''),
      'warnings', v_warnings
    ),
    p_actor_id
  )
  returning id into v_history_id;

  perform catalog.enqueue_outbox_message(
    p_tenant_id,
    'catalog.product.deactivated',
    jsonb_build_object(
      'tenant_id', p_tenant_id,
      'product_id', p_product_id,
      'previous_status', v_previous_status,
      'current_status', v_current_status,
      'reason', nullif(btrim(coalesce(p_reason, '')), '')
    )
  );

  return query
  select *
  from catalog._product_business_status_result_row(
    p_tenant_id,
    p_product_id,
    v_previous_status,
    v_current_status,
    p_reason,
    v_warnings,
    v_history_id
  );
end;
$$;

